import { ErrorBoundaryFallbackProps } from '@suspensive/react';
import { QRScanInstruction } from '~/entities/qr-scan/ui/qr-scan-instruction';
import { QrScanManualInput } from '~/entities/qr-scan/ui/qr-scan-manual-input';
import { QRScanShowTab } from '~/entities/qr-scan/ui/qr-scan-show-tab';
import { QrScanSvgMask } from '~/entities/qr-scan/ui/qr-scan-svg-mask';
import { CameraContainer, QrScanSubContainer } from '~/entities/qr-scan/ui/styled';
import { ErrorMessageBox } from '~/entities/qr-scan/ui/styled/instruction';
import i18n from '~/shared/i18n/i18n';

export const CameraErrorFallback = ({ error, reset }: ErrorBoundaryFallbackProps<any>) => {
  const message = error?.message;
  const width = window.innerWidth;
  const height = window.innerHeight;
  const handleReset = async () => {
    reset();
  };
  return (
    <>
      <QrScanSubContainer>
        <QRScanShowTab />
        <QRScanInstruction height={height} />

        <QrScanSvgMask height={height} width={width}>
          {message && (
            <ErrorMessageBox>
              {message}
              <button type="button" onClick={handleReset} className={'mt-3'}>
                {i18n.t('retry')}
              </button>
            </ErrorMessageBox>
          )}
        </QrScanSvgMask>
        <QrScanManualInput />
      </QrScanSubContainer>
      <CameraContainer id="qr-reader" />
    </>
  );
};
