import { useErrorBoundary } from '@suspensive/react';
import type QrScanner from 'qr-scanner';
import { useCallback } from 'react';
import { useStore } from '~/app/store/store';
import { QRScanErrorDialog } from '~/entities/qr-scan/lib/qr-scan-error-dialog';
import { type InvalidQRScanReason, resolveQRScanResult } from '~/entities/qr-scan/lib/resolve-qr-scan-result';
import { type QRScannerControls, useQRScannerLifecycle } from '~/entities/qr-scan/lib/use-qr-scanner-lifecycle';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';

const INVALID_SCAN_LOG_MESSAGES: Partial<Record<InvalidQRScanReason, string>> = {
  parse: 'Error parsing QR code',
  validation: 'Invalid QR code data',
};

export const useQRScanCamera = () => {
  const { navigate, navigateBack } = useNavigate();
  const { setError: setErrorBoundary } = useErrorBoundary();
  const setQRCode = useStore((state) => state.qrScannerSlice.setQRCode);

  const showErrorDialog = useCallback((controls: QRScannerControls, message?: string) => {
    controls.pause();
    QRScanErrorDialog({
      message: message ?? i18n.t('validation:invalidQRCode'),
      onConfirmClick: controls.resume,
    });
  }, []);

  const handleInvalidScan = useCallback(
    (reason: InvalidQRScanReason, controls: QRScannerControls) => {
      const logMessage = INVALID_SCAN_LOG_MESSAGES[reason];
      if (logMessage) {
        console.error(logMessage);
      }
      showErrorDialog(controls);
    },
    [showErrorDialog],
  );

  const navigateAfterSuccessfulScan = useCallback(
    (from?: string) => {
      //native에서 qr스캔시 새 창이 닫히는 현상
      if (window.ReactNativeWebView && from) {
        navigate(from, { replace: true });
        return;
      }
      navigateBack();
    },
    [navigate, navigateBack],
  );

  const handleScan = useCallback(
    (result: QrScanner.ScanResult, controls: QRScannerControls) => {
      const currentOptions = useStore.getState().qrScannerSlice.options;
      const resolution = resolveQRScanResult(result.data, currentOptions?.scannerType);

      if (resolution.status === 'invalid') {
        handleInvalidScan(resolution.reason, controls);
        return;
      }

      setQRCode(resolution.data);
      controls.clear();
      navigateAfterSuccessfulScan(currentOptions?.from);
    },
    [handleInvalidScan, navigateAfterSuccessfulScan, setQRCode],
  );

  const lifecycle = useQRScannerLifecycle({
    onInitializationError: setErrorBoundary,
    onScan: handleScan,
  });

  return {
    error: lifecycle.error,
    reset: lifecycle.reset,
    init: lifecycle.initialize,
    clear: lifecycle.clear,
  };
};
