import { memo, useRef } from 'react';
import { useQRScanCamera } from '~/entities/qr-scan/lib/use-qr-scan-camera';
import { QRScanInstruction } from '~/entities/qr-scan/ui/qr-scan-instruction';
import { QrScanManualInput } from '~/entities/qr-scan/ui/qr-scan-manual-input';
import { QRScanShowTab } from '~/entities/qr-scan/ui/qr-scan-show-tab';
import { QrScanSvgMask } from '~/entities/qr-scan/ui/qr-scan-svg-mask';
import { CameraContainer, QrScanSubContainer } from '~/entities/qr-scan/ui/styled';

export const QRScanCamera = memo(function QRScanCamera() {
  const qrReaderRef = useRef(null);
  const { width } = window.screen;
  const { height } = window.screen;

  const { error } = useQRScanCamera();

  if (error) {
    throw error;
  }

  return (
    <>
      <QrScanSubContainer>
        <QRScanShowTab />
        <QRScanInstruction height={height} />
        <QrScanSvgMask height={height} width={width} />
        <QrScanManualInput />
      </QrScanSubContainer>
      <CameraContainer id="qr-reader" ref={qrReaderRef} />
    </>
  );
});
