import { memo } from 'react';
import { useStore } from '~/app/store/store';
import { QRInstructionProp, ScannerType } from '~/entities/qr-scan/model/types';
import {
  InstructionBold,
  InstructionFlexHorizontal,
  InstructionTitle,
  InstructionTitleContainer,
} from '~/entities/qr-scan/ui/styled';

export const QRScanInstruction = memo(function QRScanInstruction({ height }: QRInstructionProp) {
  const scannerType = useStore((state) => state.qrScannerSlice.options.scannerType);

  return (
    <InstructionTitleContainer $prop={scannerType === ScannerType.PaymentQRScan ? height * 0.065 : height * 0.13}>
      <InstructionFlexHorizontal>
        <InstructionTitle>
          아래 사각형에 맞춰
          <br />
          <InstructionBold>QR코드</InstructionBold>를 스캔해 주세요.
        </InstructionTitle>
      </InstructionFlexHorizontal>
    </InstructionTitleContainer>
  );
});
