import { AllQRCode } from '~/entities/qr-code/model/types';
import { ScannerType } from '~/entities/qr-scan/model/types';

export const determineProperty = (scannerType: ScannerType): keyof AllQRCode | null => {
  const typePropertyMap: { [key in ScannerType]?: keyof AllQRCode } = {
    [ScannerType.WalletQRScan]: 'walletAddr',
    [ScannerType.PaymentQRScan]: 'txCode',
  };
  return typePropertyMap[scannerType] ?? null;
};
