import { useBlocker } from '@use-blocker';
import QrScanner from 'qr-scanner';
import { useCallback, useEffect, useRef, useState } from 'react';
import { checkCameraPermission } from '~/entities/qr-scan/lib/check-camera-permission';
import { setBackCameraForAndroid } from '~/entities/qr-scan/lib/get-back-camera';
import i18n from '~/shared/i18n/i18n';

const SCANNER_ELEMENT_ID = 'qr-reader';
const SCANNER_INITIALIZATION_TIMEOUT = 3000;

export type QRScannerControls = {
  clear: () => void;
  pause: () => void;
  resume: () => Promise<void> | undefined;
};

type QRScanHandler = (result: QrScanner.ScanResult, controls: QRScannerControls) => void;

type UseQRScannerLifecycleOptions = {
  onInitializationError: (error: Error) => void;
  onScan: QRScanHandler;
};

type QRScannerLifecycleState = {
  generation: number;
  initializationTimer: {
    generation: number;
    timer: ReturnType<typeof setTimeout>;
  } | null;
  isInitializing: boolean;
  scanner: QrScanner | null;
};

type ScannerInitializationAttempt = {
  generation: number;
  isCurrent: () => boolean;
};

class QRScannerInitializationError extends Error {}

const getScannerElement = () => {
  const element = document.getElementById(SCANNER_ELEMENT_ID) as HTMLVideoElement | null;
  if (!element) {
    throw new QRScannerInitializationError(`Element with id ${SCANNER_ELEMENT_ID} not found in DOM`);
  }
  return element;
};

const ensureCameraPermission = async () => {
  if (!(await checkCameraPermission())) {
    throw new QRScannerInitializationError(i18n.t('validation:cameraPermissionDenied'));
  }
};

const handleInitializationError = (
  caughtError: unknown,
  onInitializationError: (error: Error) => void,
  onUnexpectedError: (error: Error) => void,
) => {
  const error = caughtError instanceof Error ? caughtError : new Error(String(caughtError));
  if (error instanceof QRScannerInitializationError) {
    onInitializationError(error);
    return;
  }
  onUnexpectedError(error);
};

const beginInitialization = (lifecycle: QRScannerLifecycleState): ScannerInitializationAttempt => {
  const generation = lifecycle.generation + 1;
  lifecycle.generation = generation;
  lifecycle.isInitializing = true;

  return {
    generation,
    isCurrent: () => lifecycle.generation === generation,
  };
};

const startInitializationTimeout = (
  lifecycle: QRScannerLifecycleState,
  attempt: ScannerInitializationAttempt,
  onTimeout: () => void,
) => {
  const timer = setTimeout(() => {
    if (attempt.isCurrent()) {
      onTimeout();
    }
  }, SCANNER_INITIALIZATION_TIMEOUT);
  lifecycle.initializationTimer = { generation: attempt.generation, timer };
};

const finishInitialization = (lifecycle: QRScannerLifecycleState, attempt: ScannerInitializationAttempt) => {
  if (attempt.isCurrent()) {
    lifecycle.isInitializing = false;
  }
};

const createScanner = (element: HTMLVideoElement, onScan: (result: QrScanner.ScanResult) => void) =>
  new QrScanner(element, onScan, {
    preferredCamera: 'environment',
    highlightScanRegion: false,
    highlightCodeOutline: false,
    returnDetailedScanResult: true,
    calculateScanRegion: (video: HTMLVideoElement) => ({
      x: 0,
      y: 0,
      width: video.videoWidth,
      height: video.videoHeight,
    }),
  });

export const useQRScannerLifecycle = ({ onInitializationError, onScan }: UseQRScannerLifecycleOptions) => {
  const [error, setError] = useState<Error>();
  const lifecycleRef = useRef<QRScannerLifecycleState>({
    generation: 0,
    initializationTimer: null,
    isInitializing: false,
    scanner: null,
  });
  const controlsRef = useRef<QRScannerControls | null>(null);
  const callbacksRef = useRef({ onInitializationError, onScan });

  callbacksRef.current = { onInitializationError, onScan };

  const clearInitializationTimer = useCallback((generation?: number) => {
    const lifecycle = lifecycleRef.current;
    const initializationTimer = lifecycle.initializationTimer;
    if (!initializationTimer || (generation !== undefined && initializationTimer.generation !== generation)) {
      return;
    }

    clearTimeout(initializationTimer.timer);
    lifecycle.initializationTimer = null;
  }, []);

  const clearScanner = useCallback(() => {
    const lifecycle = lifecycleRef.current;
    lifecycle.generation += 1;
    lifecycle.isInitializing = false;
    clearInitializationTimer();

    const scanner = lifecycle.scanner;
    lifecycle.scanner = null;
    scanner?.destroy();
  }, [clearInitializationTimer]);

  const pauseScanner = useCallback(() => {
    lifecycleRef.current.scanner?.pause();
  }, []);

  const resumeScanner = useCallback(() => lifecycleRef.current.scanner?.start(), []);

  controlsRef.current = {
    clear: clearScanner,
    pause: pauseScanner,
    resume: resumeScanner,
  };

  const initializeScanner = useCallback(async () => {
    const lifecycle = lifecycleRef.current;
    if (lifecycle.scanner || lifecycle.isInitializing) {
      return;
    }

    const attempt = beginInitialization(lifecycle);

    try {
      startInitializationTimeout(lifecycle, attempt, () => {
        clearScanner();
        callbacksRef.current.onInitializationError(new Error(i18n.t('validation:initializationTimeout')));
      });

      const element = getScannerElement();
      await ensureCameraPermission();
      if (!attempt.isCurrent()) {
        return;
      }

      const scanner = createScanner(element, (result) => {
        const controls = controlsRef.current;
        if (controls) {
          callbacksRef.current.onScan(result, controls);
        }
      });
      lifecycle.scanner = scanner;

      await setBackCameraForAndroid(scanner);
      if (!attempt.isCurrent()) {
        return;
      }

      await scanner.start();
    } catch (caughtError: unknown) {
      if (!attempt.isCurrent()) {
        return;
      }

      clearScanner();
      handleInitializationError(caughtError, callbacksRef.current.onInitializationError, setError);
    } finally {
      clearInitializationTimer(attempt.generation);
      finishInitialization(lifecycle, attempt);
    }
  }, [clearInitializationTimer, clearScanner]);

  const resetScanner = useCallback(async () => {
    clearScanner();
    await initializeScanner();
  }, [clearScanner, initializeScanner]);

  useBlocker(() => lifecycleRef.current.isInitializing);

  useEffect(() => {
    void initializeScanner();
    return clearScanner;
  }, [clearScanner, initializeScanner]);

  return {
    error,
    reset: resetScanner,
    initialize: initializeScanner,
    clear: clearScanner,
  };
};
