import { memo } from 'react';
import { useStore } from '~/app/store/store';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { GuideContainer } from '~/entities/qr-scan/ui/styled';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const QrScanGuide = memo(function QrScanGuide() {
  const scannerType = useStore((state) => state.qrScannerSlice.options.scannerType);
  const { navigate } = useNavigate();
  const handleClickGuide = () => {
    navigate({ pathname: PATHS.paymentGuide, search: '?defaultTabIndex=0' });
  };

  if (scannerType === ScannerType.WalletQRScan) {
    return <></>;
  }

  return (
    <GuideContainer className="show-guide">
      <button type="button" onClick={handleClickGuide}>
        <span>&nbsp;</span>
        {i18n.t('usageGuide')}
      </button>
    </GuideContainer>
  );
});
