import { memo, useCallback } from 'react';
import { useStore } from '~/app/store/store';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { TabButton, TabButtonArea } from '~/entities/qr-scan/ui/styled';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

export const QRScanShowTab = memo(function QRScanShowTab() {
  const { navigate } = useNavigate();
  const scannerType = useStore((state) => state.qrScannerSlice.options.scannerType);

  const handleQrShowMove = useCallback(() => {
    navigate(PATHS.payment.myPaymentQRCode, { replace: true });
  }, [navigate]);

  if (scannerType === ScannerType.WalletQRScan) {
    return <></>;
  }

  return (
    <TabButtonArea>
      <TabButton type="button" className="on">
        {i18n.t('scanQR')}
      </TabButton>
      <TabButton type="button" onClick={handleQrShowMove}>
        {i18n.t('showQR')}
      </TabButton>
    </TabButtonArea>
  );
});
