import { summarizeMPM_usingParseEMVText } from '~/entities/qr-code/lib/emv';
import { AllQRCode, ParsedItems } from '~/entities/qr-code/model/types';

export const parseQRCode = (decodedText: string): AllQRCode | null => {
  try {
    return JSON.parse(decodedText);
  } catch {
    return null;
  }
};

type ParsedQRPayload = { format: 'json'; data: AllQRCode } | { format: 'emv'; data: ParsedItems };

export const parseQRCodeItems = (decodedText: string): ParsedQRPayload | null => {
  try {
    const trimmedText = decodedText.trim();

    if (trimmedText.startsWith('{') && trimmedText.endsWith('}')) {
      //송금 QR코드의 경우 JSON 형식
      const parsedObject = JSON.parse(trimmedText);
      if (parsedObject && typeof parsedObject === 'object' && !Array.isArray(parsedObject)) {
        return { format: 'json', data: parsedObject };
      }
    }

    const emvItems = summarizeMPM_usingParseEMVText(trimmedText);
    if (emvItems.length > 0) {
      return { format: 'emv', data: emvItems };
    }

    return null;
  } catch (e) {
    console.error('Error parsing QR code items:', e);
    return null;
  }
};
