import { Buffer } from 'buffer';
import { calculateCRC16, calculateCRC16Buffer } from './crc';
import { decodeTagValueMPM, TAGS_NAME_MPM } from './emvTagsMPM';

export type TLV = {
  tag: string;
  length: string;
  value: string;
};

export type ParsedQRResult = {
  format: 'CPM' | 'MPM';
  data: TLV[];
};

// --- Text/MPM Parsing (Legacy/Generator Support) ---

export function parseEMVText(payload: string): TLV[] {
  const result: TLV[] = [];
  let index = 0;

  while (index < payload.length) {
    if (index + 4 > payload.length) break;
    const tag = payload.substring(index, index + 2);
    index += 2;
    const lengthStr = payload.substring(index, index + 2);
    index += 2;
    if (!/^\d+$/.test(lengthStr)) break;
    const length = parseInt(lengthStr, 10);
    if (index + length > payload.length) break;
    const value = payload.substring(index, index + length);
    index += length;
    result.push({ tag, length: lengthStr, value });
  }
  return result;
}

// --- Auto-Detection and Unified Parsing ---

/**
 * Automatically detects QR code format and parses accordingly
 * Tries BER-TLV (Base64) first, then falls back to plain text TLV (MPM)
 * Returns both the detected format and parsed data
 */

function toHex(num: number): string {
  return num.toString(16).toUpperCase().padStart(2, '0');
}

export function parseBERTLV(buffer: Buffer): TLV[] {
  const result: TLV[] = [];
  let index = 0;

  while (index < buffer.length) {
    // 1. Parse Tag
    if (index >= buffer.length) break;
    const tagVal = buffer[index];
    let tagStr = toHex(tagVal);
    index++;

    // Check for multibyte tag (last 5 bits are 11111)
    if ((tagVal & 0x1f) === 0x1f) {
      while (index < buffer.length) {
        const nextByte = buffer[index];
        tagStr += toHex(nextByte);
        index++;
        // If MSB is 0, it's the last byte of the tag
        if ((nextByte & 0x80) === 0) break;
      }
    }

    // 2. Parse Length
    if (index >= buffer.length) break;
    const lenByte = buffer[index];
    index++;

    let length = 0;
    let lengthStrHex = ''; // We want to show the hex bytes of the length field specifically?
    // Or just the numeric length? Requirement says "Length" in table.
    // Usually we show the numeric value or the raw hex bytes.
    // For EMV tables, numeric is often more useful, but raw hex confirms structure.
    // Let's store numeric in `length` and formatted string in `lengthStr`?
    // The interface expects `length: string`. In text mode this was "04".
    // In binary mode, if length is 255, should we show "FF" or "255"?
    // "Parse... Value... Display".
    // Let's display HEX since Tag and Value are Hex.

    if ((lenByte & 0x80) === 0) {
      // Short form (1 byte)
      length = lenByte;
      lengthStrHex = toHex(lenByte);
    } else {
      // Long form
      const numberOfBytes = lenByte & 0x7f;
      lengthStrHex = toHex(lenByte); // The identifier byte

      let tempLen = 0;
      for (let i = 0; i < numberOfBytes; i++) {
        if (index >= buffer.length) break;
        const val = buffer[index];
        lengthStrHex += toHex(val);
        tempLen = (tempLen << 8) | val;
        index++;
      }
      length = tempLen;
    }

    // 3. Parse Value
    if (index + length > buffer.length) {
      console.warn('TLV Value overflow');
      break;
    }

    const valueBuffer = buffer.subarray(index, index + length);
    const valueStr = Buffer.from(valueBuffer).toString('hex').toUpperCase();
    index += length;

    result.push({
      tag: tagStr,
      length: lengthStrHex, // Showing the Raw Length Bytes (e.g. '04' or '8104')
      value: valueStr,
    });
  }

  return result;
}

export function parseQRCode(qrData: string): ParsedQRResult {
  // First, try to parse as BER-TLV (Base64 encoded)
  try {
    // Check if it looks like Base64 (common Base64 characters)
    const base64Regex = /^[A-Za-z0-9+/]+=*$/;
    if (base64Regex.test(qrData.trim())) {
      const buffer = Buffer.from(qrData, 'base64');
      const result = parseBERTLV(buffer);

      // If we successfully parsed at least one TLV, it's BER-TLV format
      if (result.length > 0) {
        return { format: 'CPM', data: result };
      }
    }
  } catch (e) {
    // If Base64 decode fails, try plain text parsing
  }

  // Fall back to plain text TLV (MPM format)
  return { format: 'MPM', data: parseEMVText(qrData) };
}

// --- Binary/CPM Parsing (BER-TLV) ---

export function parseBase64TLV(base64: string): TLV[] {
  try {
    const buffer = Buffer.from(base64, 'base64');
    return parseBERTLV(buffer);
  } catch (e) {
    console.error('Base64 decode error', e);
    return [];
  }
}

// --- Generator Logic ---

export type GeneratorOptions = {
  autoCrc?: boolean;
};

export function generateBase64FromTLV(data: TLV[], options: GeneratorOptions = { autoCrc: true }): string {
  // 1. Construct Hex String
  let rawHex = '';

  // If autoCrc is true, we strip existing '63' and append new calculation.
  // If autoCrc is false, we use data EXACTLY as provided.
  const cleanData = options.autoCrc ? data.filter((t) => t.tag !== '63') : data;

  for (const item of cleanData) {
    rawHex += item.tag + item.length + item.value;
  }

  if (options.autoCrc) {
    // 2. Append CRC Tag and Length (6304)
    rawHex += '6304';

    // 3. Convert to Buffer
    const buffer = Buffer.from(rawHex, 'hex');

    // 4. Calculate CRC16 on Buffer
    const crc = calculateCRC16Buffer(buffer);

    // 5. Append CRC to Hex
    rawHex += crc;
  }

  // 6. Convert final Hex to Base64
  return Buffer.from(rawHex, 'hex').toString('base64');
}

export function generateEMVString(data: TLV[]): string {
  // ... (keep legacy text generator if needed, or deprecate)
  // For now we keep it but typically we'll use the new one.
  let raw = '';
  const cleanData = data.filter((t) => t.tag !== '63');

  for (const item of cleanData) {
    raw += item.tag + item.length + item.value;
  }

  const crcPrefix = raw + '6304';
  const crc = calculateCRC16(Buffer.from(crcPrefix, 'hex'));

  return crcPrefix + crc;
}

type Item = { tag: string; length: number; value: string; name: string };

export function summarizeMPM_usingParseEMVText(qr: string): Item[] {
  const root = parseEMVText(qr);

  const items: Item[] = root.map((t) => ({
    tag: t.tag,
    length: Number(t.length),
    value: decodeTagValueMPM(t.tag, t.value),
    name: TAGS_NAME_MPM[t.tag] ?? '',
  }));

  const t26 = root.find((t) => t.tag === '26');
  if (t26) {
    const sub = parseEMVText(t26.value);
    items.push(
      ...sub.map((t) => ({
        tag: `26/${t.tag}`,
        length: Number(t.length),
        value: decodeTagValueMPM(t.tag, t.value),
        name: TAGS_NAME_MPM[`26/${t.tag}`] ?? '',
      })),
    );
  }
  const t62 = root.find((t) => t.tag === '62');
  if (t62) {
    const sub = parseEMVText(t62.value);
    items.push(
      ...sub.map((t) => ({
        tag: `62/${t.tag}`,
        length: Number(t.length),
        value: decodeTagValueMPM(t.tag, t.value),
        name: TAGS_NAME_MPM[`62/${t.tag}`] ?? '',
      })),
    );
  }

  return items;
}

// Alias for backward compatibility if needed, but we prefer specific names now.
export const parseEMV = parseEMVText;
